export function initRaven() {
  const root=document.documentElement; let active=null; let lastError='';
  function installStyle(){let s=document.getElementById('raven-v650-reference-vector-style');if(!s){s=document.createElement('style');s.id='raven-v650-reference-vector-style';s.textContent=rv65CSS('.rv65-layer');document.head.append(s);}}
  function motionEnabled(){return root.dataset.motion!=='off'&&window.ClubMotion?.enabled!==false}
  function canRun(explicit){return !document.hidden&&(explicit||motionEnabled())}
  function lockPage(run){const b=document.body;run.scrollY=window.scrollY||window.pageYOffset||0;run.restore={htmlOverflow:root.style.overflow,bodyOverflow:b.style.overflow,bodyPosition:b.style.position,bodyTop:b.style.top,bodyWidth:b.style.width};root.style.overflow='hidden';b.style.overflow='hidden';b.style.position='fixed';b.style.top=`-${run.scrollY}px`;b.style.width='100%';}
  function unlockPage(run){if(!run?.restore)return;const b=document.body;root.style.overflow=run.restore.htmlOverflow;b.style.overflow=run.restore.bodyOverflow;b.style.position=run.restore.bodyPosition;b.style.top=run.restore.bodyTop;b.style.width=run.restore.bodyWidth;try{window.scrollTo(0,run.scrollY||0)}catch{}}
  function schedule(run,fn,delay){const id=setTimeout(()=>{run.timers.delete(id);if(active===run)fn()},delay);run.timers.add(id);return id}
  function stopSound(run){const a=run?.audio;if(!a)return;run.audio=null;for(const n of a.nodes)try{n.stop?.()}catch{};try{a.context.close()}catch{}}
  function finish(run,reason='cancelled'){if(!run||active!==run)return;active=null;for(const id of run.timers)clearTimeout(id);run.timers.clear();stopSound(run);unlockPage(run);run.layer.remove();if(reason!=='replaced'&&reason!=='hidden'){const t=run.trigger?.isConnected?run.trigger:document.querySelector('[data-artist="raven-lin"]');t?.focus?.({preventScroll:true})}document.dispatchEvent(new CustomEvent('club:raven',{detail:{active:false,reason,version:RV65_VERSION}}));}
  function stop(reason='cancelled'){finish(active,reason)}
  function makeLayer(words,explicit){const layer=document.createElement('div');layer.className=`rv65-layer${explicit?' rv65-force':''}`;layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-label','Raven Lin Boost Mark IX transformation');layer.innerHTML=`<div class="rv65-grid" aria-hidden="true"></div><div class="rv65-aura" aria-hidden="true"></div><div class="rv65-burst" aria-hidden="true"></div><div class="rv65-flash" aria-hidden="true"></div><header class="rv65-top"><div class="rv65-brand"><i></i><b>RAVEN LIN</b><span>REFERENCE VECTOR / 6.5</span></div><div class="rv65-actions"><button type="button" data-rv65-sound aria-pressed="false">${words.sfxOff}</button><button type="button" data-rv65-skip>${words.skip} ↗</button></div></header><div class="rv65-stage">${rv65DriverSVG()}</div><div class="rv65-phase" aria-hidden="true"><div data-p="entry"><b>ENTRY</b><span>${words.entry}</span></div><div data-p="white"><b>SET</b><span>${words.white}</span></div><div data-p="red"><b>LOCK</b><span>${words.red}</span></div><div data-p="rev"><b>REVOLVE</b><span>${words.rev}</span></div><div data-p="henshin"><b>HENSHIN</b><span>${words.henshin}</span></div></div><div class="rv65-reveal"><small>2.5D VECTOR REDRAW // NO RASTER AT RUNTIME</small><strong>RAVEN <em>LIN</em></strong><span>${words.complete}</span></div><div class="rv65-progress" aria-hidden="true"><i></i></div>`;return layer;}
  function setupParts(layer){layer.querySelectorAll('.rv65-part').forEach(p=>{const x=p.dataset.px,y=p.dataset.py;if(x&&y)p.style.transformOrigin=`${x}px ${y}px`;})}
  function buildSfx(run,button,words){if(run.audio){stopSound(run);button.textContent=words.sfxOff;button.setAttribute('aria-pressed','false');return}const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){button.disabled=true;return}try{const context=new Audio(),master=context.createGain();master.gain.value=.15;master.connect(context.destination);const audio={context,master,nodes:[]};run.audio=audio;context.resume().then(()=>{if(active!==run||run.audio!==audio)return;button.textContent=words.sfxOn;button.setAttribute('aria-pressed','true');const elapsed=Math.max(0,performance.now()-run.startedAt);const cues=[[820,150,150,'square',.13],[1640,200,180,'sawtooth',.11],[2200,300,220,'square',.10],[2780,430,1300,'triangle',.075],[4320,76,820,'sine',.24]];for(const [ms,hz,dur,type,g] of cues){if(ms<=elapsed)continue;const at=context.currentTime+(ms-elapsed)/1000,osc=context.createOscillator(),gain=context.createGain();osc.type=type;osc.frequency.setValueAtTime(hz,at);osc.frequency.exponentialRampToValueAtTime(Math.max(35,hz*.45),at+dur/1000);gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(g,at+.012);gain.gain.exponentialRampToValueAtTime(.0001,at+dur/1000);osc.connect(gain);gain.connect(master);osc.start(at);osc.stop(at+dur/1000+.05);audio.nodes.push(osc);}}).catch(()=>stopSound(run));}catch{stopSound(run)}}
  function startTimeline(run){if(active!==run)return;run.startedAt=performance.now();void run.layer.offsetWidth;run.layer.classList.add('rv65-running');schedule(run,()=>finish(run,'complete'),RV65_DURATION);schedule(run,()=>{if(active!==run)return;const svg=run.layer.querySelector('.rv65-svg'),box=svg?.getBoundingClientRect();if(!box||box.width<20||box.height<20)run.layer.classList.add('rv65-safe')},500);document.dispatchEvent(new CustomEvent('club:raven',{detail:{active:true,duration:RV65_DURATION,version:RV65_VERSION,renderer:'inline-svg-reference-redraw'}}));}
  async function launch(trigger,{explicit=false}={}){stop('replaced');lastError='';if(!canRun(explicit))return false;try{installStyle();const words=WORDS[root.lang==='en'?'en':'vi'],layer=makeLayer(words,explicit),run={layer,trigger:trigger||document.activeElement,explicit,startedAt:0,timers:new Set(),audio:null,restore:null,scrollY:0};active=run;document.body.append(layer);setupParts(layer);lockPage(run);const skip=layer.querySelector('[data-rv65-skip]'),sound=layer.querySelector('[data-rv65-sound]');skip.addEventListener('click',()=>finish(run,'skipped'));sound.addEventListener('click',()=>buildSfx(run,sound,words));skip.focus({preventScroll:true});requestAnimationFrame(()=>requestAnimationFrame(()=>startTimeline(run)));return true;}catch(error){lastError=error?.message||String(error);stop('unavailable');return false;}}
  document.addEventListener('visibilitychange',()=>{if(document.hidden)stop('hidden')});document.addEventListener('club:motion',()=>{if(!motionEnabled()&&!active?.explicit)stop('motion-off')});document.addEventListener('club:language',()=>stop('language'));window.addEventListener('pagehide',()=>stop('hidden'));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active){e.preventDefault();stop('escape')}});
  const api={launch,stop,preload:()=>Promise.resolve(true),get state(){return{version:RV65_VERSION,active:!!active,elapsed:active?.startedAt?Math.max(0,performance.now()-active.startedAt):0,duration:RV65_DURATION,sound:!!active?.audio,lastError,renderer:'inline-svg-reference-redraw'}}};window.ClubRaven=api;return api;
}
